cmd:
set -uo pipefail
exec 2>&1
export GIT_NO_REPLACE_OBJECTS=1
export NO_COLOR=1 FORCE_COLOR=0
echo "QE-VERIFY-BEGIN worktree=$PWD"
D=$(git symbolic-ref -q --short refs/remotes/origin/HEAD || true)
if [ -z "$D" ] || ! git rev-parse --verify -q "$D^{commit}" >/dev/null; then
  if git rev-parse --verify -q origin/main^{commit} >/dev/null; then D=origin/main;
  elif git rev-parse --verify -q origin/master^{commit} >/dev/null; then D=origin/master;
  elif git rev-parse --verify -q main^{commit} >/dev/null; then D=main;
  elif git rev-parse --verify -q master^{commit} >/dev/null; then D=master;
  else D=""; fi
fi
if [ -n "$D" ]; then BASE=$(git merge-base "$D" HEAD 2>/dev/null || git rev-parse HEAD); else BASE=$(git rev-parse HEAD); fi
RUN_BASE=""; RB="${WICKED_RUN_BASE:-}"
if [ -n "$RB" ] && git rev-parse --verify -q "$RB^{commit}" >/dev/null; then BASE=$(git rev-parse "$RB^{commit}"); D=run-base; RUN_BASE=1; fi
echo "QE-VERIFY-BASE ref=${D:-HEAD} commit=$BASE"
PRODUCED=$( { git diff --name-only --diff-filter=AMR "$BASE" -- . ; git ls-files --others --exclude-standard ; } | sort -u )
is_test_path() {
  case "$1" in *.md|*.json|*.snap|*.txt|*.yml|*.yaml|*.toml|*.lock|*.html|*.css|*.png|*.svg) return 1;; esac
  case "$1" in *.test.*|*.spec.*|*_test.py|test_*.py|*/test_*.py|__tests__/*|*/__tests__/*) return 0;; esac
  return 1
}
pkg_has_dep() { [ -f "$1/package.json" ] && grep -Eq "\"$2\"[[:space:]]*:" "$1/package.json"; }
is_pw_dir() { ls "$1"/playwright.config.* >/dev/null 2>&1 || pkg_has_dep "$1" "@playwright/test"; }
is_vitest_dir() { pkg_has_dep "$1" vitest; }
is_jest_dir() { pkg_has_dep "$1" jest; }
is_py_dir() { [ -f "$1/pytest.ini" ] || [ -f "$1/conftest.py" ] || [ -f "$1/tox.ini" ] || { [ -f "$1/pyproject.toml" ] && grep -q "tool.pytest" "$1/pyproject.toml"; } || { [ -f "$1/setup.cfg" ] && grep -q "tool:pytest" "$1/setup.cfg"; }; }
pkg_has_nodetest() { local f="$1/package.json"; [ -f "$f" ] || return 1; grep -q "node --test" "$f"; }
is_pkg_dir() { [ -f "$1/package.json" ]; }
pkg_has_test_script() { local f="$1/package.json"; [ -f "$f" ] || return 1; grep -Eq "\"test\"[[:space:]]*:" "$f" || return 1; grep -q "no test specified" "$f" && return 1; return 0; }
nearest() { local d; d=$(dirname "$1"); while :; do if "$2" "$d"; then echo "$d"; return 0; fi; [ "$d" = "." ] && break; d=$(dirname "$d"); done; echo ""; return 1; }
find_bin() { local d="$1" up=""; while :; do if [ -x "$d/node_modules/.bin/$2" ]; then echo "${up:-./}node_modules/.bin/$2"; return 0; fi; [ "$d" = "." ] && break; d=$(dirname "$d"); up="../$up"; done; echo ""; return 1; }
find_pytest() { local d="$1" up=""; while :; do if [ -x "$d/.venv/bin/pytest" ]; then echo "${up:-./}.venv/bin/pytest"; return 0; fi; [ "$d" = "." ] && break; d=$(dirname "$d"); up="../$up"; done; if python3 -c "import pytest" >/dev/null 2>&1; then echo "python3 -m pytest"; return 0; fi; echo ""; return 1; }
resolve() {
  local d
  case "$1" in
    *.py)
      if grep -Eq "^[[:space:]]*(from|import)[[:space:]]+playwright" "$1" 2>/dev/null; then echo "playwright-python	$(dirname "$1")"; return; fi
      d=$(nearest "$1" is_py_dir); [ -n "$d" ] || d="."
      echo "pytest	$d"; return;;
  esac
  case "$1" in *.spec.*) d=$(nearest "$1" is_pw_dir); if [ -n "$d" ]; then echo "playwright	$d"; return; fi;; esac
  d=$(nearest "$1" is_vitest_dir); if [ -n "$d" ]; then echo "vitest	$d"; return; fi
  d=$(nearest "$1" is_jest_dir); if [ -n "$d" ]; then echo "jest	$d"; return; fi
  d=$(nearest "$1" is_pw_dir); if [ -n "$d" ]; then echo "playwright	$d"; return; fi
  # node:test rung: file imports node:test OR nearest package has node --test in scripts.test
  if grep -q "node:test" "$1" 2>/dev/null; then d=$(nearest "$1" is_pkg_dir); [ -n "$d" ] || d="."; printf "node-test\t%s\n" "$d"; return; fi
  d=$(nearest "$1" pkg_has_nodetest); if [ -n "$d" ]; then printf "node-test\t%s\n" "$d"; return; fi
  echo "unknown	."
}
sum_counts() { grep -E "$2" "$1" | tail -1 | awk '{s=0; for(i=1;i<=NF;i++) if($i ~ /^[0-9]+$/ && $(i+1) ~ /^(passed|failed|flaky|skipped|total)/) s+=$i; print s}'; }
collected() {
  local n="" fname="${3:-}"
  case "$1" in
    pytest) n=$(sum_counts "$2" "[0-9]+ (passed|failed)"); [ "${n:-0}" -gt 0 ] || n=$(grep -Eo "collected [0-9]+ item" "$2" | tail -1 | grep -Eo "[0-9]+");;
    vitest) n=$(sum_counts "$2" "^[[:space:]]*Tests[[:space:]]");;
    jest) n=$(grep -Eo "[0-9]+ total" "$2" | tail -1 | grep -Eo "[0-9]+");;
    playwright) n=$(sum_counts "$2" "[0-9]+ (passed|failed|flaky)");;
    playwright-python) n=$(grep -Eci "passed|\bpass\b|✓|\"checks\"|\bok\b" "$2");;
    node-test) n=$(grep -Eo "pass [0-9]+" "$2" | head -1 | grep -Eo "[0-9]+");;
    npm-test) if [ -n "$fname" ] && grep -qF "$fname" "$2" 2>/dev/null; then n=1; else n=0; fi;;
  esac
  echo "${n:-0}"
}
cnt() { printf '%s\n' "$1" | grep -Eo "[0-9]+ $2" | tail -1 | grep -Eo "^[0-9]+"; }
one() { local n; n=$(grep -Ec "$2" "$1"); [ "$n" -eq 1 ] && grep -E "$2" "$1"; }
tcounts() {
  local L="" F="" Q="" R=""
  case "$1" in
    node-test) L=$(one "$2" "^(ℹ|#) fail [0-9]+$") && F=$(printf '%s' "$L" | grep -Eo "[0-9]+$"); L=$(one "$2" "^(ℹ|#) pass [0-9]+$") && Q=$(printf '%s' "$L" | grep -Eo "[0-9]+$"); if [ -n "$F" ]; then R=$(grep -Ec "^(ℹ|#) cancelled [0-9]+$" "$2"); if [ "$R" -gt 1 ]; then F=""; elif [ "$R" -eq 1 ]; then R=$(grep -E "^(ℹ|#) cancelled [0-9]+$" "$2" | grep -Eo "[0-9]+$"); F=$((F + R)); fi; fi;;
    pytest) L=$(one "$2" "[0-9]+ (passed|failed|errors?|skipped|deselected).* in [0-9.]+s") && { F=$(cnt "$L" failed); R=$(cnt "$L" "errors?"); Q=$(cnt "$L" passed); F=$(( ${F:-0} + ${R:-0} )); Q=${Q:-0}; };;
    vitest) L=$(one "$2" "^[[:space:]]*Tests[[:space:]]") && printf '%s' "$L" | grep -Eq "[0-9]+ (passed|failed)" && { F=$(cnt "$L" failed); Q=$(cnt "$L" passed); F=${F:-0}; Q=${Q:-0}; R=$(grep -Ec "^[[:space:]]*Errors[[:space:]]+[0-9]+ errors?" "$2"); if [ "$R" -gt 1 ]; then F=""; elif [ "$R" -eq 1 ]; then R=$(grep -E "^[[:space:]]*Errors[[:space:]]+[0-9]+ errors?" "$2" | grep -Eo "[0-9]+" | head -1); F=$((F + R)); fi; };;
    jest) L=$(one "$2" "^Tests:") && printf '%s' "$L" | grep -Eq "[0-9]+ total" && R=$(one "$2" "^Test Suites:") && { F=$(cnt "$L" failed); Q=$(cnt "$L" passed); R=$(cnt "$R" failed); F=$(( ${F:-0} + ${R:-0} )); Q=${Q:-0}; };;
    playwright) if [ "$(grep -Ec "^[[:space:]]*[0-9]+ failed" "$2")" -le 1 ] && [ "$(grep -Ec "^[[:space:]]*[0-9]+ passed" "$2")" -le 1 ]; then F=$(grep -Eo "^[[:space:]]*[0-9]+ failed" "$2" | grep -Eo "[0-9]+"); Q=$(grep -Eo "^[[:space:]]*[0-9]+ passed" "$2" | grep -Eo "[0-9]+"); if [ -n "$F$Q" ] && [ "$(grep -Ec "^[[:space:]]*[0-9]+ flaky" "$2")" -le 1 ]; then R=$(grep -Eo "^[[:space:]]*[0-9]+ flaky" "$2" | grep -Eo "[0-9]+"); F=$(( ${F:-0} + ${R:-0} )); Q=${Q:-0}; else F=""; Q=""; fi; fi;;
  esac
  if [ -n "$F" ] && [ -n "$Q" ]; then echo "$F $Q"; fi
  return 0
}
no_worse() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  local HF HP BF BP
  read -r HF HP <<<"$1"; read -r BF BP <<<"$2"
  [ "$HF" -le "$BF" ] && [ "$HP" -ge "$((BP + ${3:-0}))" ] && [ $((HF+HP)) -ge $((BF+BP)) ]
}
link_env() {
  local d="$2" n
  while :; do
    for n in node_modules .venv; do
      if [ -d "$d/$n" ] && [ -d "$1/$d" ] && [ ! -e "$1/$d/$n" ]; then ln -sfn "$(cd "$d/$n" && pwd -P)" "$1/$d/$n" 2>/dev/null || true; fi
    done
    [ "$d" = "." ] && break; d=$(dirname "$d")
  done
}
NONTEST=""
CHANGED=$( { git diff --no-renames --name-only "$BASE" -- . ; git ls-files --others --exclude-standard ; } | sort -u )
while IFS= read -r g; do
  [ -n "$g" ] || continue
  case "$g" in tests/*|test/*|*/tests/*|*/test/*|__tests__/*|*/__tests__/*|e2e/*|*/e2e/*|spec/*|*/spec/*|fixtures/*|*/fixtures/*) continue;; esac
  is_test_path "$g" || NONTEST="$NONTEST $g"
done < <(printf '%s\n' "$CHANGED")
FB=0; P=0; E=0; PASS=0; FAIL=0; NX=0; PLAN=""; HARNESSES=""
not_executed() { NX=$((NX+1)); echo "QE-VERIFY: file=$1 harness=$2 pkg=$3 cmd=\"\" exit=- tests=0 status=not-executed reason=\"$4\""; echo "qe-verify: $1 — $4"; }
while IFS= read -r f; do
  [ -n "$f" ] || continue
  case "$f" in tests/PLAN-*.md|*/tests/PLAN-*.md) PLAN="$f";; esac
  is_test_path "$f" || continue
  P=$((P+1))
  R=$(resolve "$f"); H="${R%%	*}"; PKG="${R#*	}"
  rel="$f"; [ "$PKG" = "." ] || rel="${f#$PKG/}"
  case "$H" in
    playwright) BIN=$(find_bin "$PKG" playwright) || { not_executed "$f" "$H" "$PKG" "harness not available: playwright (@playwright/test) — no node_modules/.bin/playwright from $PKG up to the worktree root; install the repository dependencies in the worktree (npm ci) in the author phase. The verify path never runs npx"; continue; }; CMD=("$BIN" test "$rel");;
    vitest) BIN=$(find_bin "$PKG" vitest) || { not_executed "$f" "$H" "$PKG" "harness not available: vitest — no node_modules/.bin/vitest from $PKG up to the worktree root; install the repository dependencies in the worktree (npm ci) in the author phase. The verify path never runs npx"; continue; }; CMD=("$BIN" run "$rel");;
    jest) BIN=$(find_bin "$PKG" jest) || { not_executed "$f" "$H" "$PKG" "harness not available: jest — no node_modules/.bin/jest from $PKG up to the worktree root; install the repository dependencies in the worktree (npm ci) in the author phase. The verify path never runs npx"; continue; }; CMD=("$BIN" "$rel");;
    pytest) PT=$(find_pytest "$PKG") || { not_executed "$f" "$H" "$PKG" "harness not available: pytest — no .venv/bin/pytest from $PKG up to the worktree root and python3 cannot import pytest; a test-shaped .py file is NEVER run as a plain script (it would pass with zero assertions). Install pytest in the worktree in the author phase"; continue; }; if [ "$PT" = "python3 -m pytest" ]; then CMD=(python3 -m pytest -q "$rel"); else CMD=("$PT" -q "$rel"); fi;;
    playwright-python) python3 -c "import playwright" >/dev/null 2>&1 || { not_executed "$f" "$H" "$PKG" "harness not available: playwright (python) — python3 cannot import playwright; pip install playwright && playwright install chromium in the author phase"; continue; }; CMD=(python3 "$rel");;
    node-test) CMD=(node --test "$rel");;
    unknown)
      NPM_PKG=$(nearest "$f" is_pkg_dir); NPM_PKG="${NPM_PKG:-.}"
      if pkg_has_test_script "$NPM_PKG"; then
        H=npm-test; PKG="$NPM_PKG"; rel="$f"; [ "$PKG" = "." ] || rel="${f#$PKG/}"; CMD=(npm test)
      else
        not_executed "$f" unknown "$NPM_PKG" "no harness recognised — declare one the repository owns (playwright.config.*, vitest/jest/node:test in the nearest package.json, a pytest marker); the repository has no test script to fall back to"; continue
      fi;;
    *) not_executed "$f" "$H" "$PKG" "unrecognised harness: $H"; continue;;
  esac
  case " $HARNESSES " in *" $H|$PKG "*) ;; *) HARNESSES="$HARNESSES $H|$PKG";; esac
  echo "QE-VERIFY-RUN file=$f harness=$H pkg=$PKG cmd=\"${CMD[*]}\""
  OUT=$(mktemp "${TMPDIR:-/tmp}/qe-verify.XXXXXX") || { echo "qe-verify: FAIL — cannot create capture file for $f; check that ${TMPDIR:-/tmp} is writable"; exit 1; }
  ( cd "$PKG" && "${CMD[@]}" ) >"$OUT" 2>&1; RC=$?
  head -c 51200 <"$OUT"
  N=$(collected "$H" "$OUT" "$rel"); HC=$(tcounts "$H" "$OUT"); rm -f "$OUT"
  E=$((E+1))
  FCLASS=""
  if [ "$RC" -ne 0 ]; then
    FCLASS=produced-test-failure
    if ! git cat-file -e "$BASE:$f" 2>/dev/null; then :
    elif [ -z "$RUN_BASE" ]; then echo "QE-VERIFY-BASE-COMPARE file=$f skipped=\"no base recorded by the engine for this run (WICKED_RUN_BASE), so main's failures cannot be told apart\""
    elif [ -n "$NONTEST" ]; then echo "QE-VERIFY-BASE-COMPARE file=$f skipped=\"the run changed files that are not tests (${NONTEST# }), so main's failures cannot be told apart\""
    else
      BWT="${TMPDIR:-/tmp}/qe-base-file-$$-$RANDOM"
      if git worktree add --detach "$BWT" "$BASE" >/dev/null 2>&1; then
        link_env "$BWT" "$PKG"
        BOUT=$(mktemp "${TMPDIR:-/tmp}/qe-base-file.XXXXXX") || BOUT=""
        echo "QE-VERIFY-BASE-RUN file=$f harness=$H pkg=$PKG base=$BASE"
        ( cd "$BWT/$PKG" 2>/dev/null && "${CMD[@]}" ) >"${BOUT:-/dev/null}" 2>&1; BRC=$?
        BC=""; if [ -n "$BOUT" ]; then head -c 51200 <"$BOUT"; BC=$(tcounts "$H" "$BOUT"); rm -f "$BOUT"; fi
        git worktree remove --force "$BWT" >/dev/null 2>&1 || true
        echo "QE-VERIFY-BASE-COMPARE file=$f base_exit=$BRC head_failed_passed=\"${HC:-unread}\" base_failed_passed=\"${BC:-unread}\""
        if [ "$BRC" -ne 0 ] && [ "${N:-0}" -ge 1 ] && no_worse "$HC" "$BC" 1; then FCLASS=pre-existing-on-base; fi
      else FCLASS=unclassified; fi
    fi
  fi
  if [ "$FCLASS" = pre-existing-on-base ]; then FB=$((FB+1)); ST=failed;
  elif [ "$RC" -ne 0 ]; then FAIL=$((FAIL+1)); ST=failed;
  elif [ "${N:-0}" -lt 1 ]; then NX=$((NX+1)); E=$((E-1)); ST=not-executed; echo "qe-verify: $f — the $H runner exited 0 but reported 0 tests (nothing was collected or executed)";
  else PASS=$((PASS+1)); ST=passed; fi
  echo "QE-VERIFY: file=$f harness=$H pkg=$PKG cmd=\"${CMD[*]}\" exit=$RC tests=${N:-0} status=$ST${FCLASS:+ class=$FCLASS}"
done < <(printf '%s\n' "$PRODUCED")
C=0; CF=0
for HP in $HARNESSES; do
  H="${HP%%|*}"; PKG="${HP#*|}"
  case "$H" in
    vitest) BIN=$(find_bin "$PKG" vitest); CMD=("$BIN" run);;
    jest) BIN=$(find_bin "$PKG" jest); CMD=("$BIN");;
    pytest) PT=$(find_pytest "$PKG"); if [ "$PT" = "python3 -m pytest" ]; then CMD=(python3 -m pytest -q); else CMD=("$PT" -q); fi;;
    node-test) CMD=(npm test);;
    npm-test|*) echo "QE-VERIFY-CHECK: harness=$H pkg=$PKG skipped=full-suite (produced files ran individually)"; continue;;
  esac
  C=$((C+1))
  echo "QE-VERIFY-CHECK-RUN harness=$H pkg=$PKG cmd=\"${CMD[*]}\""
  CHECK_OUT=$(mktemp "${TMPDIR:-/tmp}/qe-check.XXXXXX") || CHECK_OUT=""
  ( cd "$PKG" && "${CMD[@]}" ) >"${CHECK_OUT:-/dev/null}" 2>&1; RC=$?
  HC=""; if [ -n "$CHECK_OUT" ]; then head -c 51200 <"$CHECK_OUT"; HC=$(tcounts "$H" "$CHECK_OUT"); rm -f "$CHECK_OUT"; fi
  CLASS=""
  if [ "$RC" -ne 0 ]; then
    BASE_WT="${TMPDIR:-/tmp}/qe-base-$$-$RANDOM"
    if git worktree add --detach "$BASE_WT" "$BASE" >/dev/null 2>&1; then
      link_env "$BASE_WT" "$PKG"
      BASE_CHECK_OUT=$(mktemp "${TMPDIR:-/tmp}/qe-base-check.XXXXXX") 2>/dev/null || BASE_CHECK_OUT=""
      echo "QE-VERIFY-CHECK-BASE-RUN harness=$H pkg=$PKG base=$BASE"
      ( cd "$BASE_WT/$PKG" 2>/dev/null && "${CMD[@]}" ) >"${BASE_CHECK_OUT:-/dev/null}" 2>&1; BASE_RC=$?
      BC=""; if [ -n "$BASE_CHECK_OUT" ]; then head -c 51200 <"$BASE_CHECK_OUT"; BC=$(tcounts "$H" "$BASE_CHECK_OUT"); rm -f "$BASE_CHECK_OUT"; fi
      git worktree remove --force "$BASE_WT" >/dev/null 2>&1 || true
      echo "QE-VERIFY-CHECK-BASE-COMPARE harness=$H pkg=$PKG base_exit=$BASE_RC head_failed_passed=\"${HC:-unread}\" base_failed_passed=\"${BC:-unread}\"${NONTEST:+ nontest_changed=\"${NONTEST# }\"}"
      if [ "$BASE_RC" -ne 0 ] && [ -z "$NONTEST" ] && no_worse "$HC" "$BC"; then CLASS=pre-existing-on-base
      else CLASS=produced-test-failure; CF=$((CF+1)); fi
    else CLASS=unclassified; CF=$((CF+1)); fi
  fi
  echo "QE-VERIFY-CHECK: harness=$H pkg=$PKG cmd=\"${CMD[*]}\" exit=$RC${CLASS:+ class=$CLASS}"
done
echo "QE-VERIFY-SUMMARY: produced=$P executed=$E passed=$PASS failed=$FAIL not_executed=$NX plan=${PLAN:-missing} checks=$C checks_failed=$CF failed_on_base=$FB"
[ "$P" -gt 0 ] || { echo "qe-verify: FAIL — the author phase produced no test files; nothing was verified, so done cannot be asserted"; exit 1; }
[ -n "$PLAN" ] || { echo "qe-verify: FAIL — no tests/PLAN-*.md was produced (the plan records every test, the command that ran it and its result)"; exit 1; }
[ "$NX" -eq 0 ] || { echo "qe-verify: FAIL — $NX produced test file(s) were never executed (no available harness, or the runner reported 0 tests); a test that never ran proves nothing"; exit 1; }
[ "$FAIL" -eq 0 ] || { echo "qe-verify: FAIL — $FAIL of $E produced test file(s) failed under the repository harness"; exit 1; }
[ "$CF" -eq 0 ] || { echo "qe-verify: FAIL — $CF repository check(s) failed with the produced tests in the tree"; exit 1; }
if [ "$FB" -eq 0 ]; then echo "qe-verify: PASS — $E produced test file(s) executed and passed under the repository harness; plan $PLAN"; else echo "qe-verify: PASS — $E produced test file(s) executed; $((E-FB)) passed and $FB fail on main too (pre-existing-on-base: on the run's recorded base the same file fails with at least as many failing tests and fewer passing ones; the review checks every failing test is main's); plan $PLAN"; fi
